sys_script_include.script:
var BookSearch = Class.create();
BookSearch.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    fetchBookDetails: function() {
        var bookGR = new GlideRecord('sn_lms_books');
		var authorGR = new GlideRecord('sn_lms_authors');
        var book_sys_id = this.getParameter('sysparm_book_sys_id');
        console.log("-------------", book_sys_id);
        bookGR.addQuery("sys_id", book_sys_id);
        bookGR.query();


        if (bookGR.next()) {
            // Construct and return the book details as JSON
			console.log("title", bookGR.book_title);
			authorGR.addQuery("sys_id", bookGR.author.toString());
			authorGR.query();
			authorGR.next();
            return JSON.stringify({
                book_title: bookGR.book_title.toString(),
                book_author: authorGR.author_name.toString(),
                genre: bookGR.genre.toString(),
                total_copies: bookGR.total_copies.toString(),
                available_copies: bookGR.available_copies.toString()
            })
        } else {
            return JSON.stringify({});
        }
    },
    type: 'BookSearch'
});
